def probe(node):
 out={'id':node['id'],'configured_ip':node['ip'],'ssh_alias':node['id']}
 for route in ('health','resources'):
  try:
   opener=urllib.request.build_opener(urllib.request.ProxyHandler({}))
   with opener.open(f'http://{node["ip"]}:{node["port"]}/{route}',timeout=4) as response:
    raw=response.read(256*1024+1)
    if len(raw)>256*1024:raise ValueError('oversized response')
    doc=json.loads(raw)
    out[route]={'identity_matches':doc.get('node')==node['id'],**{k:doc.get(k) for k in ('node','status','node_state','architecture','python','execution_ownership','slots') if k in doc}}
  except Exception as e:out[route]={'error':type(e).__name__,'detail':str(e)}
 args=['ssh','-T','-o','BatchMode=yes','-o','ConnectTimeout=5','-o','ConnectionAttempts=1','-o','StrictHostKeyChecking=yes','-o','UpdateHostKeys=no','-o','ControlMaster=no','-o','ControlPath=none','-o','PermitLocalCommand=no',node['id'],'python3 -B -']
 try:
  p=subprocess.run(args,input=REMOTE,capture_output=True,text=True,timeout=16)
  out['ssh']={'command':args,'returncode':p.returncode,'stderr':p.stderr.strip()}
  if p.returncode==0:out['ssh']['facts']=json.loads(p.stdout)
 except Exception as e:out['ssh']={'error':type(e).__name__,'detail':str(e)}
 return out
with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:results=list(pool.map(probe,nodes))
report={'time_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'scope':'read-only GET/SSH; no jobs, mounts, service or deployment mutations','nodes':results,'remote_program':REMOTE}
for row in results:
 for name,digest in row.get('ssh',{}).get('facts',{}).get('deployed_files',{}).items():
  if digest is not None:
   row['ssh']['facts'].setdefault('matches_checkout',{})[name]=hashlib.sha256((ROOT/name).read_bytes()).hexdigest()==digest
Path('/tmp/hybrid-9-4/readiness.json').write_text(json.dumps(report,indent=2)+'\n')
